// Lobby codes (D-52): six characters from an alphabet without look-alikes (no I/L/1, O/0), drawn from
// the browser's CSPRNG — 31^6 ≈ 887 million codes, so a code is effectively unguessable for the
// lifetime of a lobby. The code maps to a namespaced signaling id so lobbies never collide with other
// apps on a shared PeerJS server; an id that is somehow taken is regenerated by the host.

export const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
export const CODE_LENGTH = 6;
const ID_PREFIX = 'nightmare-carnival-v1-';

export function generateCode(rand: () => number = cryptoRand): string {
  let s = '';
  for (let i = 0; i < CODE_LENGTH; i++) s += CODE_ALPHABET[Math.floor(rand() * CODE_ALPHABET.length) % CODE_ALPHABET.length];
  return s;
}

/** Canonical form of what a player typed: upper-case, spaces and separators removed. */
export function normalizeCode(input: string): string {
  return input.toUpperCase().replace(/[\s\-_.]/g, '').slice(0, 12);
}

export function isValidCode(code: string): boolean {
  if (code.length !== CODE_LENGTH) return false;
  for (const ch of code) if (!CODE_ALPHABET.includes(ch)) return false;
  return true;
}

export function codeToPeerId(code: string): string {
  return ID_PREFIX + code;
}

/** Random secret for reconnecting to the same seat (kept in sessionStorage by the guest). */
export function randomToken(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, '0')).join('');
}

function cryptoRand(): number {
  const a = new Uint32Array(1);
  crypto.getRandomValues(a);
  return a[0] / 4294967296;
}
